payload:
$ErrorActionPreference='Stop'
$repo='C:\Users\Xxkan\local-ai-workspaces\mhw-mods'
$repoFull='fengie/mhw-mods'
Set-Location $repo

function RunGit {
  param([Parameter(ValueFromRemainingArguments=$true)][string[]]$Args)
  $out=& git @Args 2>&1
  [pscustomobject]@{Code=$LASTEXITCODE;Output=($out -join [Environment]::NewLine)}
}
function GitText {
  param([Parameter(ValueFromRemainingArguments=$true)][string[]]$Args)
  $r=RunGit @Args
  if($r.Code -ne 0){throw "git $($Args -join ' ') failed: $($r.Output)"}
  $r.Output.Trim()
}

$origin=GitText remote get-url origin
if($origin -notmatch 'fengie/mhw-mods'){throw "Unexpected origin $origin"}

# Fresh canonical truth first.
$r=RunGit fetch origin --prune
if($r.Code -ne 0){throw "initial fetch failed: $($r.Output)"}
$baseline=GitText rev-parse origin/main

# Read all required governance directly from current origin/main.
$gov=@(
 'AGENTS.md',
 'GLOBAL_GIT_DIRECTIVE.md',
 'NEXT-AGENT-START-HERE.md',
 '_AGENT_CONTEXT/CURRENT_REVISION.json',
 '_AGENT_CONTEXT/CONTINUITY_PROTOCOL.md',
 '_AGENT_CONTEXT/LEARNED_RULES.md',
 '_AGENT_CONTEXT/README_FIRST.md'
)
foreach($f in $gov){
  & git cat-file -e "origin/main:$f" 2>$null
  if($LASTEXITCODE -ne 0){throw "Missing governance on origin/main $baseline : $f"}
  [void](& git show "origin/main:$f")
}

$current=(GitText branch --show-current)
$remoteShow=GitText remote show origin
$defaultBranch=(($remoteShow|Select-String 'HEAD branch:'|ForEach-Object{($_ -split ':',2)[1].Trim()})|Select-Object -First 1)
if(-not $defaultBranch){$defaultBranch='main'}

$worktrees=[System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
foreach($line in (& git worktree list --porcelain)){
  if($line -like 'branch refs/heads/*'){
    [void]$worktrees.Add($line.Substring('branch refs/heads/'.Length))
  }
}

# GitHub PR/protection state is mandatory for remote deletion safety.
& gh auth status *> $null
if($LASTEXITCODE -ne 0){throw 'GitHub CLI auth unavailable; refusing branch deletion without PR/protection checks.'}

$openHeads=[System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
$completedHeads=[System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
$prNotes=@{}
$openJson=& gh pr list --repo $repoFull --state open --limit 250 --json number,title,headRefName,isDraft 2>$null
if($LASTEXITCODE -ne 0){throw 'Could not list open PRs.'}
foreach($p in ($openJson|ConvertFrom-Json)){
  if($p.headRefName){
    [void]$openHeads.Add([string]$p.headRefName)
    $prNotes[[string]$p.headRefName]="open PR #$($p.number): $($p.title)"
  }
}
$allJson=& gh pr list --repo $repoFull --state all --limit 250 --json number,title,headRefName,state,mergedAt,closedAt 2>$null
if($LASTEXITCODE -ne 0){throw 'Could not list PR history.'}
foreach($p in ($allJson|ConvertFrom-Json)){
  if(-not $p.headRefName){continue}
  $h=[string]$p.headRefName
  if($p.mergedAt){
    [void]$completedHeads.Add($h)
    if(-not $prNotes.ContainsKey($h)){$prNotes[$h]="merged PR #$($p.number): $($p.title)"}
  } elseif($p.state -eq 'CLOSED'){
    [void]$completedHeads.Add($h)
    if(-not $prNotes.ContainsKey($h)){$prNotes[$h]="closed PR #$($p.number): $($p.title)"}
  }
}
$prot=@{}
$branchJson=& gh api --method GET "repos/$repoFull/branches?per_page=100" 2>$null
if($LASTEXITCODE -ne 0){throw 'Could not read branch protection flags.'}
foreach($b in ($branchJson|ConvertFrom-Json)){$prot[[string]$b.name]=[bool]$b.protected}

function LocalBranches {
  @(& git for-each-ref --format='%(refname:strip=2)' refs/heads |
    Where-Object{$_ -and $_ -ne 'main'} | Sort-Object -Unique)
}
function RemoteBranches {
  @(& git for-each-ref --format='%(refname:strip=3)' refs/remotes/origin |
    Where-Object{$_ -and $_ -ne 'HEAD' -and $_ -ne 'main'} | Sort-Object -Unique)
}
function PatchEquivalentToMain([string]$ref){
  $ch=@(& git cherry origin/main $ref 2>$null)
  if($LASTEXITCODE -ne 0){return $false}
  return @($ch|Where-Object{$_ -like '+ *'}).Count -eq 0
}
function Classify([string]$name,[string]$ref,[bool]$remote){
  $aheadRaw=& git rev-list --count "origin/main..$ref" 2>$null
  if($LASTEXITCODE -ne 0){
    return [pscustomobject]@{Name=$name;Ahead=$null;Safe=$false;Bucket='uncertain';Reason='could not compute unique commit count'}
  }
  $ahead=[int]$aheadRaw
  if($name -eq 'main' -or $name -eq $defaultBranch){
    return [pscustomobject]@{Name=$name;Ahead=$ahead;Safe=$false;Bucket='active';Reason='canonical/default branch'}
  }
  if($name -like 'release/*'){
    return [pscustomobject]@{Name=$name;Ahead=$ahead;Safe=$false;Bucket='active';Reason='release branch retained by policy'}
  }
  if($name -eq 'heaven-bridge'){
    return [pscustomobject]@{Name=$name;Ahead=$ahead;Safe=$false;Bucket='active';Reason='Heaven Local Bridge infrastructure branch'}
  }
  if($worktrees.Contains($name)){
    return [pscustomobject]@{Name=$name;Ahead=$ahead;Safe=$false;Bucket='active';Reason='checked out in a local worktree'}
  }
  if((-not $remote) -and $name -eq $current){
    return [pscustomobject]@{Name=$name;Ahead=$ahead;Safe=$false;Bucket='active';Reason='currently checked out branch'}
  }
  if($openHeads.Contains($name)){
    return [pscustomobject]@{Name=$name;Ahead=$ahead;Safe=$false;Bucket='active';Reason=$prNotes[$name]}
  }
  if($remote -and $prot.ContainsKey($name) -and $prot[$name]){
    return [pscustomobject]@{Name=$name;Ahead=$ahead;Safe=$false;Bucket='active';Reason='protected branch'}
  }

  # Exact ancestry is the strongest safe case.
  if($ahead -eq 0){
    $note=if($prNotes.ContainsKey($name)){$prNotes[$name]}else{'all branch commits already reachable from origin/main'}
    return [pscustomobject]@{Name=$name;Ahead=$ahead;Safe=$true;Bucket='safe';Reason=$note}
  }

  # Squash/rebase/cherry-pick integration: every unique-looking commit has patch-equivalent content on main.
  if(PatchEquivalentToMain $ref){
    $note=if($prNotes.ContainsKey($name)){$prNotes[$name]}else{'all non-ancestor commits are patch-equivalent to origin/main'}
    return [pscustomobject]@{Name=$name;Ahead=$ahead;Safe=$true;Bucket='safe';Reason=$note}
  }

  # Closed/merged PR alone is NOT enough when unique non-equivalent commits remain.
  if($completedHeads.Contains($name)){
    return [pscustomobject]@{Name=$name;Ahead=$ahead;Safe=$false;Bucket='uncertain';Reason="completed PR exists but $ahead non-equivalent commit(s) remain; preserved"}
  }
  return [pscustomobject]@{Name=$name;Ahead=$ahead;Safe=$false;Bucket='unique';Reason="$ahead unique/non-equivalent commit(s) not proven represented on origin/main"}
}

# Baseline inventories.
$localBefore=LocalBranches
$remoteBefore=RemoteBranches
$initialLocal=@($localBefore|ForEach-Object{Classify $_ $_ $false})
$initialRemote=@($remoteBefore|ForEach-Object{Classify $_ "origin/$_" $true})

# Race check immediately before deletions; if main moved, reclassify all.
$r=RunGit fetch origin --prune
if($r.Code -ne 0){throw "pre-delete fetch failed: $($r.Output)"}
$baseline2=GitText rev-parse origin/main
if($baseline2 -ne $baseline){
  $baseline=$baseline2
  $localBefore=LocalBranches
  $remoteBefore=RemoteBranches
  $initialLocal=@($localBefore|ForEach-Object{Classify $_ $_ $false})
  $initialRemote=@($remoteBefore|ForEach-Object{Classify $_ "origin/$_" $true})
}

$deletedLocal=[System.Collections.Generic.List[string]]::new()
$deletedRemote=[System.Collections.Generic.List[string]]::new()
$failures=[System.Collections.Generic.List[string]]::new()
$deleteEvidence=[System.Collections.Generic.List[string]]::new()

# Local safe branches.
foreach($c in ($initialLocal|Where-Object Safe)){
  $re=Classify $c.Name $c.Name $false
  if(-not $re.Safe){continue}
  $d=RunGit branch -D -- $c.Name
  if($d.Code -eq 0){
    $deletedLocal.Add($c.Name)
    $deleteEvidence.Add("local $($c.Name): $($re.Reason)")
  } else {
    $failures.Add("local $($c.Name): $($d.Output)")
  }
}

# Remote safe branches with per-branch revalidation.
foreach($c in ($initialRemote|Where-Object Safe)){
  & git show-ref --verify --quiet "refs/remotes/origin/$($c.Name)"
  if($LASTEXITCODE -ne 0){continue}
  $re=Classify $c.Name "origin/$($c.Name)" $true
  if(-not $re.Safe){continue}
  $d=RunGit push origin --delete $c.Name
  if($d.Code -eq 0){
    $deletedRemote.Add($c.Name)
    $deleteEvidence.Add("remote $($c.Name): $($re.Reason)")
  } else {
    $failures.Add("remote $($c.Name): $($d.Output)")
  }
}

$prune=RunGit fetch origin --prune
$localAfter=LocalBranches
$remoteAfter=RemoteBranches
$remaining=@($remoteAfter|ForEach-Object{Classify $_ "origin/$_" $true})

$presActive=@($remaining|Where-Object{$_.Bucket -eq 'active'}|ForEach-Object{"$($_.Name) :: ahead=$($_.Ahead) :: $($_.Reason)"})
$presUnique=@($remaining|Where-Object{$_.Bucket -eq 'unique'}|ForEach-Object{"$($_.Name) :: ahead=$($_.Ahead) :: $($_.Reason)"})
$presUncertain=@($remaining|Where-Object{$_.Bucket -eq 'uncertain'}|ForEach-Object{"$($_.Name) :: ahead=$($_.Ahead) :: $($_.Reason)"})

$anomalies=[System.Collections.Generic.List[string]]::new()
if($current -ne 'main'){$anomalies.Add("cleanup checkout current branch is '$current'; it was preserved")}
foreach($x in $remaining|Where-Object{$_.Ahead -eq 0}){
  $anomalies.Add("$($x.Name) is fully contained by main but retained: $($x.Reason)")
}
foreach($f in $failures){$anomalies.Add("DELETE FAILURE: $f")}

[ordered]@{
  repository_path=$repo
  origin_main_sha=$baseline
  default_branch=$defaultBranch
  current_branch=$current
  local_branch_count_before=1+$localBefore.Count
  remote_branch_count_before=1+$remoteBefore.Count
  branches_deleted_locally=@($deletedLocal)
  branches_deleted_remotely=@($deletedRemote)
  deletion_evidence=@($deleteEvidence)
  branches_preserved_active_release_protected=@($presActive)
  branches_preserved_unique=@($presUnique)
  branches_preserved_uncertain=@($presUncertain)
  stale_refs_pruned=($prune.Code -eq 0)
  prune_output=$prune.Output
  pr_branch_anomalies=@($anomalies)
  deletion_failures=@($failures)
  final_local_branch_count=1+$localAfter.Count
  final_remote_branch_count=1+$remoteAfter.Count
  final_local_branches=@('main')+$localAfter
  final_remote_branches=@('main')+$remoteAfter
  no_known_unique_work_destroyed=($failures.Count -eq 0)
}|ConvertTo-Json -Depth 8
